 const [[scan]]=await serviceProbe(env,[["SELECT revision,(SELECT scanned_revision FROM gsis_roster_audit_scan WHERE scope='roster') scanned_revision FROM gsis_edge_heads WHERE scope='roster'"]]);if(!selected&&scan.scanned_revision===scan.revision)return {exported:0,exports:[]};
