async function calendarSnapshot(env){const today=edgeRosterClock().today,year=Number(today.slice(0,4)),from=year+'-01-01',to=(year+1)+'-12-31',dates=[];for(let value=Date.parse(from);value<=Date.parse(to);value+=86400000)dates.push(new Date(value).toISOString().slice(0,10));if(!env.CALENDAR_APPS_SCRIPT_URL||!gsisApiSecret(env,'CALENDAR_PROXY_SECRET'))fail(503,'ROSTER_CALENDAR_CONFIG','Configure the Calendar adapter before refreshing references.');const output={};for(let start=0;start<dates.length;start+=62){const part=dates.slice(start,start+62),response=await fetch(env.CALENDAR_APPS_SCRIPT_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'rosterDates',payload:{dates:part},service:'gsis-roster-notifier-v1',proxySecret:gsisApiSecret(env,'CALENDAR_PROXY_SECRET'),requestId:crypto.randomUUID()}),signal:AbortSignal.timeout(20000),redirect:'follow'}),result=await response.json(),rows=result.result?.dates;if(!result.ok||!Array.isArray(rows)||rows.length!==part.length||new Set(rows.map(row=>row.date)).size!==part.length)fail(503,'ROSTER_CALENDAR_REFRESH','Calendar references could not be verified. The prior snapshot remains intact.');for(const row of rows){if(!part.includes(row.date)||!['odd','even',null].includes(row.parity??null)||![true,false,null,undefined].includes(row.schoolDay))fail(503,'ROSTER_CALENDAR_REFRESH','Calendar references failed validation.');output[row.date]={...row,available:row.code!=='YEAR_UNAVAILABLE'&&typeof row.schoolDay==='boolean'};}}return output;}
