export async function refreshEdgeRosterReferences(env,{force=false}={}){const now=Date.now();if(!force){try{const [[row]]=await serviceProbe(env,[["SELECT json_extract(value_json,'$.value') checked_at,EXISTS(SELECT 1 FROM gsis_edge_records WHERE scope='roster-references' AND collection='contacts' AND record_id='$') contacts_present FROM gsis_edge_records WHERE scope='roster-references' AND collection='contactsCheckedAt' AND record_id='$'"]],'roster-references');if(row?.contacts_present&&Number.isFinite(row.checked_at)&&now-row.checked_at<120000)return {refreshed:false,fresh:true};}catch{}}let old;try{old=await readEdgeRosterReferences(env,{allowExpired:true});}catch{}const fresh=await signedBridge(env,{operation:'edgeReferences'}),contacts=fresh.contacts;if(!Array.isArray(contacts?.rosterPeople)||!Array.isArray(contacts?.rosterSMCIds)||!Array.isArray(contacts?.rosterAdminIds))fail(503,'ROSTER_CONTACTS_REFRESH','Contacts did not return complete authority.');const calendar=force||!old?.calendarCheckedAt||now-old.calendarCheckedAt>300000?await calendarSnapshot(env):old.calendarByDate;const statisticsCalendar=calendar===old?.calendarByDate?old.statisticsCalendar:await calendarStatisticsSnapshot(env).catch(()=>old?.statisticsCalendar||null);const next={schema:1,contacts,contactsCheckedAt:now,contactsSource:fresh.contactsSource||null,calendarByDate:calendar,statisticsCalendar,calendarCheckedAt:calendar===old?.calendarByDate?old.calendarCheckedAt:now};await replaceReferenceState(env,next,'roster-service');return {refreshed:true,contactsCheckedAt:now,calendarCheckedAt:next.calendarCheckedAt,dates:Object.keys(calendar).length};}
